CREATE TABLE partners (id SERIAL PRIMARY KEY, partner_name VARCHAR(255) UNIQUE NOT NULL, partner_type VARCHAR(100), contact_person VARCHAR(255), email VARCHAR(255), phone VARCHAR(50), company_website VARCHAR(500), commission_rate NUMERIC(5,2), status VARCHAR(50), onboarded_date DATE, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE partner_commissions (id SERIAL PRIMARY KEY, partner_id INTEGER REFERENCES partners(id), booking_id INTEGER, commission_amount NUMERIC(12,2), commission_percentage NUMERIC(5,2), payment_status VARCHAR(50), payment_date DATE, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE partner_promotions (id SERIAL PRIMARY KEY, partner_id INTEGER REFERENCES partners(id), promotion_name VARCHAR(255), promo_code VARCHAR(100), discount_percent NUMERIC(5,2), valid_from DATE, valid_until DATE, is_active BOOLEAN);
CREATE TABLE partner_performance (id SERIAL PRIMARY KEY, partner_id INTEGER REFERENCES partners(id), report_month INTEGER, report_year INTEGER, total_bookings INTEGER, total_commission NUMERIC(15,2), customers_referred INTEGER, retention_rate NUMERIC(5,2));
CREATE TABLE partner_documents (id SERIAL PRIMARY KEY, partner_id INTEGER REFERENCES partners(id), document_type VARCHAR(100), document_name VARCHAR(255), file_url VARCHAR(500), expiry_date DATE, uploaded_at TIMESTAMPTZ);
